<template>
  <main class="dashboard-page">
    <header class="dashboard-head"><div><h1>{{ t("dashboard.title") }}</h1><p>{{ t("dashboard.subtitle") }}</p></div><div class="controls"><label>{{ t("dashboard.range") }}<a-select :value="state.rangeKind.value" @update:value="state.setRangeKind"><a-select-option v-for="range in ranges" :key="range" :value="range">{{ t(`dashboard.${range}`) }}</a-select-option></a-select></label><label>{{ t("dashboard.timezone") }}<a-select :value="state.timezone.value" show-search @update:value="state.setTimezone"><a-select-option v-for="zone in timezones" :key="zone" :value="zone">{{ zone }}</a-select-option></a-select></label><a-button :loading="state.loading.value" :aria-label="t('dashboard.refresh')" @click="state.refresh">↻</a-button></div></header>
    <section v-if="state.rangeKind.value === 'custom'" class="custom-range" :aria-label="t('dashboard.custom')"><label>{{ t("dashboard.from") }}<input type="datetime-local" :value="state.customFromLocal.value" @input="state.setCustomInput('from', ($event.target as HTMLInputElement).value)" /></label><label>{{ t("dashboard.to") }}<input type="datetime-local" :value="state.customToLocal.value" @input="state.setCustomInput('to', ($event.target as HTMLInputElement).value)" /></label><p v-if="!state.customValidation.value.valid" role="alert">{{ t(`dashboard.error.${state.customValidation.value.code}`) }}</p><a-button type="primary" :disabled="!state.customValidation.value.valid" @click="state.refresh">{{ t("dashboard.apply") }}</a-button></section>
    <a-alert v-if="state.errorCode.value" type="error" show-icon :message="t(`dashboard.error.${state.errorCode.value}`)" class="mb-3" />
    <nav class="section-tabs" :aria-label="t('dashboard.sections')"><button v-for="item in sections" :key="item" type="button" :aria-pressed="section === item" :class="{ active: section === item }" @click="section = item">{{ t(`dashboard.${item}`) }}</button></nav>
    <a-spin :spinning="state.loading.value && !response"><template v-if="response"><div class="metadata"><span>{{ t("dashboard.rangeEnd") }}: {{ formatDateTime(response.to, response.timezone, locale) }}</span><span>{{ t("dashboard.asOf") }}: {{ formatDateTime(response.asOf, response.timezone, locale) }}</span></div>
      <section v-show="section === 'overview'" class="stack" data-testid="dashboard-section-overview"><div class="metric-grid six"><DashboardMetricCard :title="t('dashboard.monitoringVolume')" :value="formatCount(monitoringValue, locale)" :result="data.overview.monitoringVolume" clickable :selected="overviewTrend === 'monitoringVolume'" @select="overviewTrend = 'monitoringVolume'" /><DashboardMetricCard :title="t('dashboard.agentDuration')" :value="formatDuration(countValue(data.overview.agentDuration))" :result="data.overview.agentDuration" clickable :selected="overviewTrend === 'agentDuration'" @select="overviewTrend = 'agentDuration'" /><DashboardMetricCard :title="t('dashboard.modelRequests')" :value="formatCount(countValue(data.overview.modelRequests), locale)" :result="data.overview.modelRequests" clickable :selected="overviewTrend === 'modelRequests'" @select="overviewTrend = 'modelRequests'" /><DashboardMetricCard :title="t('dashboard.modelSuccessRate')" :value="formatRatio(ratioValue(data.overview.modelSuccessRate), locale)" :result="data.overview.modelSuccessRate" clickable :selected="overviewTrend === 'modelSuccessRate'" @select="overviewTrend = 'modelSuccessRate'" /><DashboardMetricCard :title="t('dashboard.cacheHitRate')" :value="formatRatio(ratioValue(data.overview.cacheHitRate), locale)" :result="data.overview.cacheHitRate" clickable :selected="overviewTrend === 'cacheHitRate'" @select="overviewTrend = 'cacheHitRate'" /><DashboardGitMetricCard :title="t('dashboard.commits')" :value="formatCount(countValue(data.overview.gitCommits), locale)" :result="data.overview.gitCommits" :selected="overviewTrend === 'gitCommits'" test-id="overview-metric-gitCommits" @select="overviewTrend = 'gitCommits'" /></div><DashboardTrendChart :title="t(`dashboard.${overviewTrend}`)" :kind="overviewKinds[overviewTrend]" :panel="data.overviewTrends[overviewTrend]" :git-metadata="overviewTrend === 'gitCommits' ? data.overviewTrends.gitCommits : undefined" :test-id="`overview-trend-${overviewTrend}`" :timezone="response.timezone" /><a-alert v-if="configurationChanged" type="warning" show-icon :message="t('dashboard.configurationChanged')" /><DashboardDomainSummary :result="data.exceptions.domainHealth" /><section v-if="monitoringDiagnostic" class="panel"><h3>{{ t("dashboard.configurationDiagnostic") }}</h3><p>{{ t("dashboard.configurationVersion") }}: {{ monitoringDiagnostic.version }} · {{ t("dashboard.configuredDomains") }}: {{ monitoringDiagnostic.domains }}</p></section></section>
      <section v-show="section === 'agent'" class="stack" data-testid="dashboard-section-agent"><section v-for="group in agentMetricGroups" :key="group.title" class="metric-group"><h3>{{ t(`dashboard.${group.title}`) }}</h3><div class="metric-grid five"><DashboardMetricCard v-for="metric in group.metrics" :key="metric.key" :title="t(`dashboard.${metric.key}`)" :value="metric.value" :result="metric.result" :clickable="Boolean(metric.trend)" :selected="metric.trend === agentTrend" :test-id="`agent-metric-${metric.key}`" @select="selectAgentTrend(metric.trend)" /></div></section><MetricTabs v-model="agentTrend" :keys="agentTrendKeys" /><DashboardTrendChart :title="t(`dashboard.${agentTrend}`)" :kind="agentKinds[agentTrend]" :panel="data.agent.trends[agentTrend]" :test-id="`agent-trend-${agentTrend}`" :timezone="response.timezone" /><section class="panel"><header><h3>{{ t("dashboard.runScope") }}</h3><div><button v-for="scope in scopes" :key="scope" type="button" :aria-pressed="runScope === scope" @click="runScope = scope">{{ t(`dashboard.${scope}`) }}</button></div></header><template v-if="data.agent.runTerminalDistribution.status !== 'unavailable'"><div class="distribution"><span v-for="row in data.agent.runTerminalDistribution.data[runScope]" :key="row.status">{{ t(`dashboard.runStatus.${row.status}`) }}: {{ formatCount(row.count, locale) }}</span></div><p v-if="data.agent.runTerminalDistribution.status === 'partial'">{{ t(`dashboard.reason.${data.agent.runTerminalDistribution.partialReason}`) }}</p></template><p v-else>{{ t(`dashboard.reason.${data.agent.runTerminalDistribution.unavailableReason}`) }}</p></section><div class="three"><DashboardDataPanels :title="t('dashboard.runType')" :panel="data.agent.runTypeDistribution" /><DashboardDataPanels :title="t('dashboard.messageType')" :panel="data.agent.messageTypeDistribution" /><DashboardDataPanels :title="t('dashboard.toolStatus')" :panel="data.agent.toolStatusDistribution" /></div><DashboardTables :title="t('dashboard.toolDetails')" :panel="data.agent.toolDetails" table-kind="tools" /></section>
      <section v-show="section === 'model'" class="stack" data-testid="dashboard-section-model"><section v-for="group in modelMetricGroups" :key="group.title" class="metric-group"><h3>{{ t(`dashboard.${group.title}`) }}</h3><div class="metric-grid five"><DashboardMetricCard v-for="metric in group.metrics" :key="metric.key" :title="t(`dashboard.${metric.key}`)" :value="metric.value" :result="metric.result" :clickable="Boolean(metric.trend)" :selected="metric.trend === modelTrend" :test-id="`model-metric-${metric.key}`" @select="selectModelTrend(metric.trend)" /></div></section><MetricTabs v-model="modelTrend" :keys="modelTrendKeys" /><DashboardTrendChart :title="t(`dashboard.${modelTrend}`)" :kind="modelKinds[modelTrend]" :panel="data.model.trends[modelTrend]" :test-id="`model-trend-${modelTrend}`" :timezone="response.timezone" /><DashboardMetricCard :title="t('dashboard.timeoutKindBreakdown')" :value="timeoutBreakdown" :result="data.model.metrics.timeoutKindBreakdown" /><section class="stack"><h3>{{ t("dashboard.tokenCoverage") }}</h3><div class="metric-grid four"><DashboardMetricCard :title="t('dashboard.inputTokenCoverage')" :value="formatRatio(ratioValue(data.model.metrics.inputTokenCoverage), locale)" :result="data.model.metrics.inputTokenCoverage" /><DashboardMetricCard :title="t('dashboard.outputTokenCoverage')" :value="formatRatio(ratioValue(data.model.metrics.outputTokenCoverage), locale)" :result="data.model.metrics.outputTokenCoverage" /><DashboardMetricCard :title="t('dashboard.totalTokenCoverage')" :value="formatRatio(ratioValue(data.model.metrics.totalTokenCoverage), locale)" :result="data.model.metrics.totalTokenCoverage" /><DashboardMetricCard :title="t('dashboard.inputCacheCoverage')" :value="formatRatio(ratioValue(data.model.metrics.inputCacheCoverage), locale)" :result="data.model.metrics.inputCacheCoverage" /></div></section><DashboardTables :title="t('dashboard.byModel')" :panel="data.model.byModel" table-kind="models" /></section>
      <section v-show="section === 'git'" class="stack" data-testid="dashboard-section-git"><div class="metric-grid five"><DashboardGitMetricCard :title="t('dashboard.commits')" :value="formatCount(countValue(data.git.metrics.commits), locale)" :result="data.git.metrics.commits" :selected="gitTrend === 'commits'" test-id="git-metric-commits" @select="gitTrend = 'commits'" /><DashboardGitMetricCard :title="t('dashboard.nonMergeCommits')" :value="formatCount(countValue(data.git.metrics.nonMergeCommits), locale)" :result="data.git.metrics.nonMergeCommits" :selected="gitTrend === 'nonMergeCommits'" test-id="git-metric-nonMergeCommits" @select="gitTrend = 'nonMergeCommits'" /><DashboardGitMetricCard :title="t('dashboard.filesChanged')" :value="formatCount(countValue(data.git.metrics.filesChanged), locale)" :result="data.git.metrics.filesChanged" :selected="gitTrend === 'filesChanged'" test-id="git-metric-filesChanged" @select="gitTrend = 'filesChanged'" /><DashboardGitMetricCard :title="t('dashboard.linesAdded')" :value="formatCount(countValue(data.git.metrics.linesAdded), locale)" :result="data.git.metrics.linesAdded" :selected="gitTrend === 'linesAdded'" test-id="git-metric-linesAdded" @select="gitTrend = 'linesAdded'" /><DashboardGitMetricCard :title="t('dashboard.linesDeleted')" :value="formatCount(countValue(data.git.metrics.linesDeleted), locale)" :result="data.git.metrics.linesDeleted" :selected="gitTrend === 'linesDeleted'" test-id="git-metric-linesDeleted" @select="gitTrend = 'linesDeleted'" /></div><MetricTabs v-model="gitTrend" :keys="gitTrendKeys" /><DashboardTrendChart :title="t(`dashboard.${gitTrend}`)" kind="count" :panel="data.git.trends[gitTrend]" :git-metadata="data.git.trends[gitTrend]" :test-id="`git-trend-${gitTrend}`" :timezone="response.timezone" /><DashboardGitHeatmap :result="data.exceptions.gitHeatmap180d" :timezone="response.timezone" /></section>
      <section v-show="section === 'worker'" class="stack" data-testid="dashboard-section-worker"><DashboardWorkerSnapshot :result="workerLive" :timezone="response.timezone" /><div class="metric-grid four"><DashboardMetricCard v-for="metric in workerMetrics" :key="metric.key" :title="t(`dashboard.${metric.key}`)" :value="metric.value" :result="metric.result" /></div><DashboardTrendChart :title="t('dashboard.restarts')" kind="worker_events" :panel="data.worker.eventTrend" :timezone="response.timezone" /><DashboardRestartRecords :result="data.worker.restartRecords" :timezone="response.timezone" /><DashboardDomainHealth :result="data.exceptions.domainHealth" :timezone="response.timezone" /></section>
    </template><a-empty v-else-if="!state.loading.value" :description="t('dashboard.noData')" /></a-spin>
  </main>
</template>
<script setup lang="ts">
import { computed, inject, onMounted, ref } from "vue"; import { useI18n } from "vue-i18n"; import type { AnalyticsRangeKind, DashboardData, MetricResult } from "@agent-workbench/shared"; import { createDashboardState } from "../dashboard-state"; import { dashboardQueryKey } from "../dashboard-injection"; import { queryDashboard } from "../dashboard-api"; import { supportedTimezones } from "../dashboard-timezone"; import { formatCount, formatDateTime, formatDuration, formatRatio } from "../dashboard-formatters"; import DashboardMetricCard from "../components/DashboardMetricCard.vue"; import DashboardTrendChart from "../components/DashboardTrendChart.vue"; import DashboardDataPanels from "../components/DashboardDataPanels.vue"; import DashboardTables from "../components/DashboardTables.vue"; import DashboardGitHeatmap from "../components/DashboardGitHeatmap.vue"; import DashboardDomainHealth from "../components/DashboardDomainHealth.vue"; import DashboardWorkerSnapshot from "../components/DashboardWorkerSnapshot.vue"; import DashboardGitMetricCard from "../components/DashboardGitMetricCard.vue"; import DashboardRestartRecords from "../components/DashboardRestartRecords.vue"; import DashboardDomainSummary from "../components/DashboardDomainSummary.vue"; import MetricTabs from "../components/DashboardMetricTabs.vue"; import type { DashboardSection, CountResult, RatioResult, NullableCountResult } from "../dashboard-types"; import { metricNumberValue, metricNullableCountValue, metricRatioValue } from "../dashboard-types";
const { t, locale } = useI18n(); const state = createDashboardState(inject(dashboardQueryKey, queryDashboard)); onMounted(() => { void state.refresh(); }); const response = computed(() => state.response.value); const data = computed<DashboardData>(() => response.value!.data); const section = ref<DashboardSection>("overview"); const sections: DashboardSection[] = ["overview", "agent", "model", "git", "worker"]; const ranges: AnalyticsRangeKind[] = ["preset_24h", "preset_7d", "preset_30d", "preset_90d", "custom"]; const timezones = supportedTimezones();
const overviewTrend = ref<keyof DashboardData["overviewTrends"]>("monitoringVolume"); const overviewKinds = { monitoringVolume: "monitoring", agentDuration: "duration", modelRequests: "model_status", modelSuccessRate: "ratio", cacheHitRate: "ratio", gitCommits: "count" } as const;
const agentTrendKeys = ["totalDuration", "runCount", "primaryRunCount", "subtaskRunCount", "userMessageCount", "assistantMessageCount", "toolCallCount", "toolSuccessRate", "manualCompactionCount", "autoCompactionCount"] as const; const agentTrend = ref<(typeof agentTrendKeys)[number]>("runCount"); const agentKinds = { totalDuration: "duration", runCount: "count", primaryRunCount: "count", subtaskRunCount: "count", userMessageCount: "count", assistantMessageCount: "count", toolCallCount: "count", toolSuccessRate: "ratio", manualCompactionCount: "count", autoCompactionCount: "count" } as const;
const modelTrendKeys = ["requests", "successRate", "timeoutRate", "completedAverageDuration", "tokens", "cacheHitRate"] as const; const modelTrend = ref<(typeof modelTrendKeys)[number]>("requests"); const modelKinds = { requests: "model_status", successRate: "ratio", timeoutRate: "ratio", completedAverageDuration: "duration", tokens: "tokens", cacheHitRate: "ratio" } as const;
const gitTrendKeys = ["commits", "nonMergeCommits", "filesChanged", "linesAdded", "linesDeleted"] as const; const gitTrend = ref<(typeof gitTrendKeys)[number]>("commits"); const scopes = ["all", "main", "subtask"] as const; const runScope = ref<(typeof scopes)[number]>("all");
function countValue(result: CountResult): number | null { return metricNumberValue(result); } function ratioValue(result: RatioResult): number | null { return metricRatioValue(result); } function nullableCountValue(result: NullableCountResult): number | null { return metricNullableCountValue(result); } function monitoringCount(result: DashboardData["overview"]["monitoringVolume"]) { return result.status === "unavailable" ? null : result.value.count; }
const timeoutBreakdown = computed(() => { const result = data.value.model.metrics.timeoutKindBreakdown; return result.status === "unavailable" ? "—" : `${result.value.idle}/${result.value.total}/${result.value.none}`; }); const monitoringValue = computed(() => monitoringCount(data.value.overview.monitoringVolume)); const configurationChanged = computed(() => { const result = data.value.overview.monitoringVolume; return result.status !== "unavailable" && result.value.configurationChangedWithinRange; }); const monitoringDiagnostic = computed(() => { const result = data.value.overview.monitoringVolume; return result.status === "unavailable" ? null : { version: result.value.collectionConfigVersion, domains: result.value.configuredDomainsAtAsOf.join(", ") }; });
function selectAgentTrend(key: string | undefined) { if (key && (agentTrendKeys as readonly string[]).includes(key)) agentTrend.value = key as (typeof agentTrendKeys)[number]; } function selectModelTrend(key: string | undefined) { if (key && (modelTrendKeys as readonly string[]).includes(key)) modelTrend.value = key as (typeof modelTrendKeys)[number]; }
type MetricDisplay = { key: string; value: string; result: MetricResult<unknown>; trend?: string };
function display(key: string, result: MetricResult<unknown>, value: string, trend?: string): MetricDisplay { return { key, result, value, trend }; }
const agentMetrics = computed<MetricDisplay[]>(() => { const m = data.value.agent.metrics; return [
  display("totalDuration", m.totalDuration, formatDuration(countValue(m.totalDuration)), "totalDuration"),
  display("runCount", m.runCount, formatCount(countValue(m.runCount), locale.value), "runCount"),
  display("primaryRunCount", m.primaryRunCount, formatCount(countValue(m.primaryRunCount), locale.value), "primaryRunCount"),
  display("subtaskRunCount", m.subtaskRunCount, formatCount(countValue(m.subtaskRunCount), locale.value), "subtaskRunCount"),
  display("userMessageCount", m.userMessageCount, formatCount(countValue(m.userMessageCount), locale.value), "userMessageCount"),
  display("assistantMessageCount", m.assistantMessageCount, formatCount(countValue(m.assistantMessageCount), locale.value), "assistantMessageCount"),
  display("toolCallCount", m.toolCallCount, formatCount(countValue(m.toolCallCount), locale.value), "toolCallCount"),
  display("toolSuccessRate", m.toolSuccessRate, formatRatio(ratioValue(m.toolSuccessRate), locale.value), "toolSuccessRate"),
  display("manualCompactionCount", m.manualCompactionCount, formatCount(countValue(m.manualCompactionCount), locale.value), "manualCompactionCount"),
  display("autoCompactionCount", m.autoCompactionCount, formatCount(countValue(m.autoCompactionCount), locale.value), "autoCompactionCount"),
]; });
const modelMetrics = computed<MetricDisplay[]>(() => { const m=data.value.model.metrics; return [display("requestCount",m.requestCount,formatCount(countValue(m.requestCount),locale.value), "requests"),display("successRate",m.successRate,formatRatio(ratioValue(m.successRate),locale.value), "successRate"),display("timeoutRate",m.timeoutRate,formatRatio(ratioValue(m.timeoutRate),locale.value), "timeoutRate"),display("completedAverageDuration",m.completedAverageDuration,formatDuration(m.completedAverageDuration.status === "unavailable" ? null : m.completedAverageDuration.value.durationMs), "completedAverageDuration"),display("inputTokens",m.inputTokens,formatCount(nullableCountValue(m.inputTokens),locale.value), "tokens"),display("outputTokens",m.outputTokens,formatCount(nullableCountValue(m.outputTokens),locale.value), "tokens"),display("totalTokens",m.totalTokens,formatCount(nullableCountValue(m.totalTokens),locale.value), "tokens"),display("cacheReadTokens",m.cacheReadTokens,formatCount(nullableCountValue(m.cacheReadTokens),locale.value), "tokens"),display("cacheHitRate",data.value.overview.cacheHitRate,formatRatio(ratioValue(data.value.overview.cacheHitRate),locale.value), "cacheHitRate"),display("inputReportedCount",m.inputReportedCount,formatCount(countValue(m.inputReportedCount),locale.value)),display("outputReportedCount",m.outputReportedCount,formatCount(countValue(m.outputReportedCount),locale.value)),display("totalReportedCount",m.totalReportedCount,formatCount(countValue(m.totalReportedCount),locale.value)),display("totalDerivedCount",m.totalDerivedCount,formatCount(countValue(m.totalDerivedCount),locale.value)),display("cacheComparableCount",m.cacheComparableCount,formatCount(countValue(m.cacheComparableCount),locale.value)),display("inputTokenCoverage",m.inputTokenCoverage,formatRatio(ratioValue(m.inputTokenCoverage),locale.value)),display("outputTokenCoverage",m.outputTokenCoverage,formatRatio(ratioValue(m.outputTokenCoverage),locale.value)),display("totalTokenCoverage",m.totalTokenCoverage,formatRatio(ratioValue(m.totalTokenCoverage),locale.value)),display("inputCacheCoverage",m.inputCacheCoverage,formatRatio(ratioValue(m.inputCacheCoverage),locale.value))]; });
const agentMetricGroups = computed(() => [{ title: "agentRunMetrics", metrics: agentMetrics.value.slice(0, 4) }, { title: "agentActivityMetrics", metrics: agentMetrics.value.slice(4, 8) }, { title: "agentCompactionMetrics", metrics: agentMetrics.value.slice(8) }]); const modelMetricGroups = computed(() => [{ title: "modelRequestMetrics", metrics: modelMetrics.value.slice(0, 4) }, { title: "modelTokenMetrics", metrics: modelMetrics.value.slice(4, 8) }, { title: "modelReportingMetrics", metrics: modelMetrics.value.slice(8) }]); const workerMetrics = computed<MetricDisplay[]>(() => { const m=data.value.worker.metrics; return [display("unexpectedExits",m.unexpectedExits,formatCount(countValue(m.unexpectedExits),locale.value)),display("restartAttempts",m.restartAttempts,formatCount(countValue(m.restartAttempts),locale.value)),display("restartSucceeded",m.restartSucceeded,formatCount(countValue(m.restartSucceeded),locale.value)),display("restartFailed",m.restartFailed,formatCount(countValue(m.restartFailed),locale.value))]; });
const workerLive = computed(() => data.value.exceptions.workerLiveSnapshot);
</script>
<style scoped>.dashboard-page{height:100%;overflow:auto;padding:28px;color:var(--text-color)}.dashboard-head{display:flex;justify-content:space-between;gap:16px}.dashboard-head h1{margin:0;font-size:24px}.dashboard-head p,.metadata,.panel p{color:var(--text-color-secondary)}.controls,.controls label,.custom-range,.metadata,.panel header{display:flex;align-items:center;gap:8px}.controls label{font-size:12px}.controls .ant-select{min-width:145px}.custom-range{margin:14px 0;flex-wrap:wrap}.custom-range input{display:block}.custom-range p{color:#dc2626;font-size:12px}.section-tabs,.metric-tabs{display:flex;gap:6px;border-bottom:1px solid var(--border-color);margin:14px 0}.section-tabs button,.metric-tabs button,.panel header button{border:0;background:transparent;color:var(--text-color-secondary);padding:8px;cursor:pointer}.section-tabs button.active,.metric-tabs button[aria-pressed=true],.panel header button[aria-pressed=true]{color:var(--primary-color);border-bottom:2px solid var(--primary-color)}.metadata{justify-content:flex-end;font-size:12px}.stack{display:grid;gap:14px}.metric-group{display:grid;gap:8px}.metric-group h3{font-size:14px;margin:0}.metric-grid{display:grid;gap:12px}.metric-grid.six{grid-template-columns:repeat(6,minmax(0,1fr))}.metric-grid.five{grid-template-columns:repeat(5,minmax(0,1fr))}.metric-grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.panel{background:var(--panel-bg-elevated);border:1px solid var(--border-color);border-radius:8px;padding:14px}.panel h3{margin:0;font-size:14px}.distribution{display:flex;flex-wrap:wrap;gap:10px;margin-top:10px}.distribution span,.snapshot{font-size:12px;padding:8px;background:var(--panel-bg);border-radius:5px}.snapshot{display:grid;gap:6px}.snapshot b{font-size:20px}.panel table{width:100%;border-collapse:collapse;margin-top:8px;font-size:12px}.panel th,.panel td{padding:8px;text-align:left;border-top:1px solid var(--border-color)}@media(max-width:1100px){.metric-grid.six,.metric-grid.five{grid-template-columns:repeat(3,minmax(0,1fr))}.three{grid-template-columns:1fr}}@media(max-width:700px){.dashboard-head{flex-direction:column}.controls{flex-wrap:wrap}.metric-grid.six,.metric-grid.five,.metric-grid.four{grid-template-columns:repeat(2,minmax(0,1fr))}.metadata{justify-content:start;flex-wrap:wrap}}</style>
